const input=$json.body??$json;
const s=v=>String(v??'').trim();
const n=v=>Number(v);
const strategy=input.offer_strategy??input.strategy??{};
const approval=input.offer_approval??input.approval??{};
const identity=input.identity??{};
const leadId=s(identity.lead_id??input.lead_id);
const propertyId=s(identity.property_id??input.property_id);
const dealId=s(identity.deal_id??input.deal_id);
const requestId=s(input.request_id??strategy.request_id??approval.request_id);
const recommended=n(strategy.recommended_offer??input.recommended_offer??input.offer_amount);
const target=n(strategy.target_offer??input.target_offer??recommended);
const mao=n(strategy.mao_ceiling??input.mao_ceiling??input.mao);
const opening=n(strategy.opening_offer??input.opening_offer??target);
const negotiationRoomPct=Math.min(25,Math.max(0,n(strategy.negotiation_room_pct??input.negotiation_room_pct??5)));
const underwritingApproved=['approved','ready','proceed','approved_with_conditions'].includes(s(input.underwriting_status??strategy.underwriting_status).toLowerCase());
const strategyReady=s(strategy.status??input.strategy_status).toLowerCase()==='ready';
const approvalStatus=s(approval.status??input.approval_status).toLowerCase();
const approvalReady=approvalStatus==='dispatch_ready'||input.human_approval===true||input.approval_granted===true;
const missing=[];
if(!leadId)missing.push('lead_id');
if(!propertyId&&!dealId)missing.push('property_or_deal_id');
if(!Number.isFinite(recommended)||recommended<=0)missing.push('recommended_offer');
if(!Number.isFinite(target)||target<=0)missing.push('target_offer');
if(!Number.isFinite(mao)||mao<=0)missing.push('mao_ceiling');
if(!Number.isFinite(opening)||opening<=0)missing.push('opening_offer');
if(Number.isFinite(target)&&Number.isFinite(mao)&&target>mao)missing.push('target_exceeds_mao');
if(Number.isFinite(opening)&&Number.isFinite(mao)&&opening>mao)missing.push('opening_exceeds_mao');
if(!underwritingApproved)missing.push('approved_underwriting');
if(!strategyReady)missing.push('offer_strategy_ready');
const concessionBudget=Math.max(0,mao-target);
const requestedRoom=Math.min(concessionBudget,Math.max(0,target*negotiationRoomPct/100));
const minimumAcceptable=Math.max(0,target-requestedRoom);
const counterBands={
  preferred:{min:target,max:Math.min(mao,target+requestedRoom)},
  workable:{min:minimumAcceptable,max:mao},
  walk_away:{below:minimumAcceptable},
  hard_ceiling:mao
};
const packageStatus=missing.length?'blocked':(approvalReady?'ready':'approval_required');
const negotiationState=packageStatus==='blocked'?'human_review':packageStatus==='approval_required'?'initial_offer':'initial_offer';
const packageId='offer-package:'+s(dealId||propertyId||leadId||'unknown')+':'+s(requestId||'unknown')+':v1';
const activity={
  activity_type:'seller_offer_package',
  subject:'AI seller offer package '+packageStatus,
  body:[
    'Seller offer package generated by Wholesaling OS.',
    'Opening offer: '+String(opening),
    'Target offer: '+String(target),
    'MAO ceiling: '+String(mao),
    'Concession budget: '+String(concessionBudget),
    'Negotiation room: '+String(negotiationRoomPct)+'%',
    'Minimum acceptable: '+String(minimumAcceptable),
    'Package status: '+packageStatus,
    'Negotiation state: '+negotiationState
  ].join('\n'),
  lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,
  external_id:packageId,external_source:'wholesaling-os-offer-package',
  metadata:{package_id:packageId,request_id:requestId||null,opening_offer:opening,target_offer:target,recommended_offer:recommended,mao_ceiling:mao,negotiation_room_pct:negotiationRoomPct,concession_budget:concessionBudget,minimum_acceptable:minimumAcceptable,counter_bands:counterBands,package_status:packageStatus,negotiation_state:negotiationState}
};
return [{json:{
  ok:packageStatus!=='blocked',
  status:packageStatus,
  package_id:packageId,
  request_id:requestId||null,
  identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},
  seller_offer_package:{
    opening_offer:opening,
    target_offer:target,
    recommended_offer:recommended,
    mao_ceiling:mao,
    concession_budget:concessionBudget,
    concession_budget_pct:mao>0?(concessionBudget/mao)*100:0,
    minimum_acceptable:minimumAcceptable,
    negotiation_room_pct:negotiationRoomPct,
    counter_bands:counterBands,
    response_options:['accept','counter','reject','needs_time','asks_questions']
  },
  negotiation:{
    state:negotiationState,
    next_states:['counter_received','counter_evaluated','accepted','rejected','stalled','human_review'],
    counter_must_be_evaluated_against_mao:true,
    economics_must_remain_viable:true
  },
  transaction_context:{
    assignment:input.assignment??strategy.assignment??null,
    novation:input.novation??strategy.novation??null,
    double_close:input.double_close??strategy.double_close??null
  },
  guardrails:{
    never_exceed_mao:true,
    never_negative_offer:true,
    approved_underwriting_required:true,
    strategy_ready_required:true,
    every_counter_rechecked:true,
    no_auto_accept_above_or_below_policy_bounds:true
  },
  crm_activity:activity,
  missing_requirements:[...new Set(missing)],
  next_workflow:packageStatus==='blocked'?'human_review':approvalReady?'wf-036-offer-lifecycle':'wf-117-offer-approval-negotiation-gate'
}}];
